mapper.select:
SELECT a.id, a.actor_id, u.username AS actor_username, a.operation,
       a.target_id, a.reason, a.trace_id, a.created_at
FROM admin_audit a
JOIN app_user u ON u.id = a.actor_id

    AND a.actor_id = #{request.actorId}
    AND a.operation = #{request.operation}
    AND a.target_id = #{request.targetId}
    AND a.created_at >= #{request.from}
    AND a.created_at <= #{request.to}

        AND (a.created_at < #{anchor.createdAt}
             OR (a.created_at = #{anchor.createdAt} AND a.id < #{anchor.id}))


ORDER BY a.created_at DESC, a.id DESC
LIMIT #{fetchSize}
